/* Focused harness for HAProxy src/mjson.c mystrtod().
 *
 * The mjson source under test is injected at compile time:
 *   -DMJSON_SRC='"/abs/path/to/src/mjson.c"'
 * so that the static mystrtod() is directly reachable for unit testing.
 * The repository include dir must be passed as -I<repo>/include.
 *
 * Modes:
 *   normal          run numeric correctness checks vs libc strtod (exit 0 ok)
 *   exp <literal>   parse <literal> with mystrtod(); abort via SIGALRM after
 *                   ALARM_SECONDS and exit 124 if still running
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>

#include MJSON_SRC

#ifndef ALARM_SECONDS
#define ALARM_SECONDS 2
#endif

static void on_alarm(int sig)
{
	(void)sig;
	/* write(2) is async-signal-safe */
	const char msg[] = "TIMEOUT: mystrtod did not return before alarm\n";
	(void)!write(2, msg, sizeof(msg) - 1);
	_exit(124);
}

static int nearly_equal(double a, double b)
{
	double diff, scale;

	if (isinf(a) || isinf(b))
		return isinf(a) && isinf(b) && ((a > 0) == (b > 0));
	if (isnan(a) || isnan(b))
		return isnan(a) && isnan(b);
	diff = fabs(a - b);
	scale = fabs(a) > fabs(b) ? fabs(a) : fabs(b);
	if (scale < 1e-300)
		return diff < 1e-300;
	return diff <= 1e-12 * scale;
}

static int mode_normal(void)
{
	static const char *cases[] = {
		"1e2", "1e-2", "2.5e-5", "1.5e10", "9.99e3", "-3e2",
		"1e0", "1E3", "0.5e1", "123.456e-3", "7.25e2", "1e10",
		"2.2250738585072014e-308"
	};
	int failures = 0;
	size_t i;

	for (i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
		char *end = NULL, *end2 = NULL;
		double got = mystrtod(cases[i], &end);
		double ref = strtod(cases[i], &end2);

		if (!nearly_equal(got, ref)) {
			fprintf(stderr, "FAIL %s: mystrtod=%.17g strtod=%.17g\n",
			        cases[i], got, ref);
			failures++;
		} else {
			printf("ok   %-26s -> %.17g\n", cases[i], got);
		}
		(void)end;
		(void)end2;
	}
	if (failures) {
		fprintf(stderr, "%d numeric check(s) failed\n", failures);
		return 1;
	}
	printf("all %zu numeric checks passed\n",
	       sizeof(cases) / sizeof(cases[0]));
	return 0;
}

static int mode_exp(const char *literal)
{
	struct timespec t0, t1;
	char *end = NULL;
	double d;
	double ms;

	signal(SIGALRM, on_alarm);
	alarm(ALARM_SECONDS);

	clock_gettime(CLOCK_MONOTONIC, &t0);
	d = mystrtod(literal, &end);
	clock_gettime(CLOCK_MONOTONIC, &t1);

	alarm(0);
	ms = (t1.tv_sec - t0.tv_sec) * 1000.0 +
	     (t1.tv_nsec - t0.tv_nsec) / 1e6;

	printf("mystrtod(\"%s\") = %g (isinf=%d) end_offset=%ld elapsed_ms=%.3f\n",
	       literal, d, isinf(d) ? 1 : 0,
	       end ? (long)(end - literal) : -1L, ms);
	return 0;
}

int main(int argc, char **argv)
{
	if (argc >= 2 && strcmp(argv[1], "normal") == 0)
		return mode_normal();
	if (argc >= 3 && strcmp(argv[1], "exp") == 0)
		return mode_exp(argv[2]);
	fprintf(stderr, "usage: %s normal | exp <literal>\n", argv[0]);
	return 2;
}

